package ai.taskforge.api; import ai.taskforge.knowledge.KnowledgeService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/knowledge") public class KnowledgeController { private final KnowledgeService knowledge;public KnowledgeController(KnowledgeService k){knowledge=k;} record AskRequest(@NotBlank @Size(max=1000) String question){} @PostMapping("/ask") KnowledgeService.Answer ask(@Valid @RequestBody AskRequest request){return knowledge.answer(request.question());} @GetMapping("/search") Object search(@RequestParam @NotBlank String q){return knowledge.search(q,6);} }
